const AUTHOR_NAME='Korosium';const AVAILABLE_MODES=['Hash','HMAC'];const AVAILABLE_HASH_FUNCTIONS={'Old':['MD5','SHA-1'],'SHA-2':['SHA-224','SHA-256','SHA-384','SHA-512'],'SHA-3':['SHA3-224','SHA3-256','SHA3-384','SHA3-512']};const AVAILABLE_HASH_ENCODING=['Binary','Octal','Decimal','Hex','Base32 (RFC-4648)','Base32 (Extended hex)','Base32 (z-base)','Base32 (Crockford)','Base64'];let stored_checksum=[];const mode_select=document.getElementById('mode-select');const hash_algorithm_select=document.getElementById('hash-algorithm-select');const hash_encoding_select=document.getElementById('hash-encoding-select');const hash_rounds_input=document.getElementById('hash-rounds-input');const hmac_length_input=document.getElementById('hmac-length-input');const hmac_key_input=document.getElementById('hmac-key-input');const hash_rounds_div=document.getElementById('hash-rounds-div');const hmac_length_div=document.getElementById('hmac-length-div');const hmac_key_div=document.getElementById('hmac-key-div');const text_textarea=document.getElementById('text-textarea');const file_input=document.getElementById('file-input');const checksum_input=document.getElementById('checksum-input');const checksum_input_label=document.getElementById('checksum-input-label');mode_select.onchange=()=>change_mode();hash_algorithm_select.onchange=()=>change_algorithm();hash_encoding_select.onchange=()=>show_hash_on_screen();hash_rounds_input.oninput=()=>process_the_right_input();hmac_length_input.oninput=()=>show_hash_on_screen();hmac_key_input.oninput=()=>process_the_right_input();text_textarea.oninput=()=>hash_or_hmac_text();file_input.oninput=()=>hash_or_hmac_file();checksum_input.onclick=()=>navigator.clipboard.writeText(checksum_input.value);const process_the_right_input=()=>{change_setting_display_values();if(mode_select.value===AVAILABLE_MODES[0]){if(file_input.files.length>0)hash_file();else hash_text();}else{if(file_input.files.length>0)hmac_file();else hmac_text();}};const hash_or_hmac_text=()=>mode_select.value===AVAILABLE_MODES[0]?hash_text():hmac_text();const hash_or_hmac_file=()=>mode_select.value===AVAILABLE_MODES[0]?hash_file():hmac_file();const hash_text=()=>{file_input.value='';stored_checksum=hash_with_right_algo_and_rounds(text_textarea.value,hash_algorithm_select.value,hash_rounds_input.value);show_hash_on_screen();};const hmac_text=()=>{file_input.value='';stored_checksum=hmac_with_right_algo(hmac_key_input.value,text_textarea.value,hash_algorithm_select.value);show_hash_on_screen();};const hash_file=()=>{text_textarea.value='';checksum_input.value='Calculating hash...';const fr=new FileReader();fr.onload=()=>{stored_checksum=hash_with_right_algo_and_rounds(fr.result,hash_algorithm_select.value,hash_rounds_input.value);show_hash_on_screen();};fr.onerror=()=>{console.log(fr.error);};fr.readAsArrayBuffer(file_input.files[0]);};const hmac_file=()=>{text_textarea.value='';checksum_input.value='Calculating HMAC...';const fr=new FileReader();fr.onload=()=>{stored_checksum=hmac_with_right_algo(hmac_key_input.value,fr.result,hash_algorithm_select.value);show_hash_on_screen();};fr.onerror=()=>{console.log(fr.error);};fr.readAsArrayBuffer(file_input.files[0]);};const hash_with_right_algo_and_rounds=(data,algo,rounds)=>{let retval=hash_once(data,algo);for(let i=1;i<rounds;i++)retval=hash_once(retval,algo);return retval;};const hash_once=(data,algo)=>{switch(algo){case AVAILABLE_HASH_FUNCTIONS['Old'][0]:return md5.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['Old'][1]:return sha1.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][0]:return sha224.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][1]:return sha256.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][2]:return sha384.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][3]:return sha512.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][0]:return sha3_224.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][1]:return sha3_256.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][2]:return sha3_384.hash.array(data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][3]:return sha3_512.hash.array(data);}};const hmac_with_right_algo=(key,data,algo)=>{switch(algo){case AVAILABLE_HASH_FUNCTIONS['Old'][0]:return md5.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['Old'][1]:return sha1.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][0]:return sha224.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][1]:return sha256.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][2]:return sha384.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-2'][3]:return sha512.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][0]:return sha3_224.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][1]:return sha3_256.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][2]:return sha3_384.hmac.array(key,data);case AVAILABLE_HASH_FUNCTIONS['SHA-3'][3]:return sha3_512.hmac.array(key,data);}};const change_mode=()=>{reset_all_fields();change_algorithm();};const change_algorithm=()=>{calculate_new_hmac_maximum_length();process_the_right_input();};const change_setting_display_values=()=>{if(mode_select.value===AVAILABLE_MODES[0]){hash_rounds_div.style.display='inline-block';hmac_length_div.style.display='none';hmac_key_div.style.display='none';}else{hash_rounds_div.style.display='none';hmac_length_div.style.display='inline-block';hmac_key_div.style.display='inline-block';}};const reset_all_fields=()=>{hmac_key_input.value='';text_textarea.value='';file_input.value='';hash_rounds_input.value=1;hmac_length_input.value=1;};const calculate_new_hmac_maximum_length=()=>{const current_max_hmac_length=hash_with_right_algo_and_rounds("",hash_algorithm_select.value,1).length;hmac_length_input.max=current_max_hmac_length;hmac_length_input.value=current_max_hmac_length;};const show_hash_on_screen=()=>{clamp_value(hash_rounds_input);clamp_value(hmac_length_input);const hmac_label=mode_select.value===AVAILABLE_MODES[1]?'HMAC-':'';const hmac_truncated_checksum=mode_select.value===AVAILABLE_MODES[1]?stored_checksum.slice(0,hmac_length_input.value):stored_checksum;const hmac_length=mode_select.value===AVAILABLE_MODES[1]&&hmac_length_input.value<stored_checksum.length?` | ${hmac_truncated_checksum.length * 8} bits`:'';let retval='';switch(hash_encoding_select.value){case AVAILABLE_HASH_ENCODING[0]:retval=to_binary(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[1]:retval=to_octal(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[2]:retval=BigInt(`0x${to_hex(hmac_truncated_checksum)}`);break;case AVAILABLE_HASH_ENCODING[3]:retval=to_hex(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[4]:retval=base32.RFC_4648.encode(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[5]:retval=base32.BASE_32_HEX.encode(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[6]:retval=base32.Z_BASE_32.encode(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[7]:retval=base32.CROCKFORD_BASE_32.encode(hmac_truncated_checksum);break;case AVAILABLE_HASH_ENCODING[8]:retval=btoa(hmac_truncated_checksum.map(x=>String.fromCharCode(x)).join(''));break;}let rounds='';if(parseInt(hash_rounds_input.value)===2&&hash_algorithm_select.value==='SHA-256')rounds='d';else if(parseInt(hash_rounds_input.value)>1)rounds=` (x${hash_rounds_input.value})`;checksum_input_label.innerHTML=`${hmac_label}${hash_algorithm_select.value}${rounds} | ${hash_encoding_select.value}${hmac_length}`;checksum_input.value=retval;};const to_desired_base=(checksum,radix,padding)=>{let retval='';for(let i=0;i<checksum.length;i++){retval+=checksum[i].toString(radix).padStart(padding,'0');}return retval;};const to_binary=checksum=>to_desired_base(checksum,2,8);const to_octal=checksum=>to_desired_base(checksum,8,3);const to_hex=(checksum)=>to_desired_base(checksum,16,2);const clamp_value=e=>{let rounds=parseInt(e.value);if(isNaN(rounds))e.value=e.min;else if(rounds<e.min)e.value=e.max;else if(rounds>e.max)e.value=e.max;};const fill_select=(select,array)=>{const type=Object.prototype.toString.call(array);if(type==='[object Object]'){const keys=Object.keys(array);for(let i=0;i<keys.length;i++){const option_group=document.createElement('optgroup');option_group.label=keys[i];option_group.innerHTML=keys[i];for(let j=0;j<array[keys[i]].length;j++){const option=document.createElement('option');option.value=array[keys[i]][j];option.innerHTML=array[keys[i]][j];option_group.append(option);}select.append(option_group);}}else if(type==='[object Array]'){for(let i=0;i<array.length;i++){const option=document.createElement('option');option.value=array[i];option.innerHTML=array[i];select.append(option);}}};const init=()=>{fill_select(mode_select,AVAILABLE_MODES);fill_select(hash_algorithm_select,AVAILABLE_HASH_FUNCTIONS);fill_select(hash_encoding_select,AVAILABLE_HASH_ENCODING);hash_rounds_input.min=1;hash_rounds_input.max=10000;hmac_length_input.min=1;mode_select.value="Hash";hash_algorithm_select.value='SHA-256';hash_encoding_select.value='Hex';hash_rounds_input.value=1;reset_all_fields();process_the_right_input();document.getElementsByTagName('footer')[0].innerHTML+=`<p>Copyright ${new Date().getFullYear()} ${AUTHOR_NAME}</p>`;};const main=()=>{init();};window.onload=main;